:root {
  --bg-card: #ffffff;
  --bg-header: #1a1a2e;
  --bg-featured: #f0f4ff;
  --bg-row-alt: #fafafa;
  --bg-full: #fff5f5;
  --color-title: #ffffff;
  --color-label: #a0a8d0;
  --color-time: #1a1a2e;
  --color-name: #1a1a2e;
  --color-meta: #888888;
  --color-spots: #3b82f6;
  --color-full: #ef4444;
  --color-footer-note: #888888;
  --border-card: #e5e7eb;
  --border-row: #f0f0f0;
  --tag-yoga-bg: #ede9fe;
  --tag-yoga-text: #7c3aed;
  --tag-hiit-bg: #fef3c7;
  --tag-hiit-text: #d97706;
  --tag-pilates-bg: #d1fae5;
  --tag-pilates-text: #059669;
  --tag-spin-bg: #fce7f3;
  --tag-spin-text: #db2777;
  --tag-box-bg: #fee2e2;
  --tag-box-text: #dc2626;
  --btn-bg: #3b82f6;
  --btn-text: #ffffff;
  --week-badge-bg: #2d2d4e;
  --week-badge-text: #a0a8d0;
  --featured-border: #6366f1;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.schedule-card {
  background: var(--bg-card);
  border: 1px solid var(--border-card);
  border-radius: 16px;
  width: 500px;
  overflow: hidden;
}

.card-header {
  background: var(--bg-header);
  padding: 16px 20px 14px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.gym-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--color-label);
  text-transform: uppercase;
}

.card-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--color-title);
  margin: 0;
  flex: 1;
}

.week-badge {
  background: var(--week-badge-bg);
  color: var(--week-badge-text);
  font-size: 11px;
  font-weight: 500;
  padding: 4px 10px;
  border-radius: 20px;
}

.class-list {
  padding: 8px 0;
}

.class-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 20px;
  border-bottom: 1px solid var(--border-row);
}

.class-row:nth-child(even) {
  background: var(--bg-row-alt);
}

.class-row.featured {
  background: var(--bg-featured);
  border-left: 3px solid var(--featured-border);
  padding-left: 17px;
}

.class-row.full {
  background: var(--bg-full);
}

.class-time {
  font-size: 13px;
  font-weight: 700;
  color: var(--color-time);
  width: 42px;
  flex-shrink: 0;
}

.class-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.class-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-name);
}

.class-meta {
  font-size: 11px;
  color: var(--color-meta);
}

.class-tag {
  font-size: 11px;
  font-weight: 600;
  padding: 3px 9px;
  border-radius: 20px;
  flex-shrink: 0;
}

.tag-yoga  { background: var(--tag-yoga-bg);    color: var(--tag-yoga-text); }
.tag-hiit  { background: var(--tag-hiit-bg);    color: var(--tag-hiit-text); }
.tag-pilates { background: var(--tag-pilates-bg); color: var(--tag-pilates-text); }
.tag-spin  { background: var(--tag-spin-bg);    color: var(--tag-spin-text); }
.tag-box   { background: var(--tag-box-bg);     color: var(--tag-box-text); }

.spots-left {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-spots);
  width: 46px;
  text-align: right;
  flex-shrink: 0;
}

.spots-left.full-text {
  color: var(--color-full);
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  border-top: 1px solid var(--border-row);
}

.footer-note {
  font-size: 12px;
  color: var(--color-footer-note);
}

.book-btn {
  background: var(--btn-bg);
  color: var(--btn-text);
  border: none;
  border-radius: 8px;
  padding: 8px 18px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
